-- Removes everything demo-data.sql added and returns the two pre-existing dev accounts to their earlier state.

DELETE FROM ticket_audit_entry
WHERE ticket_id IN (SELECT id FROM ticket WHERE organization_id IN ('00000000-0000-0000-0000-0000000b0001',
    '00000000-0000-0000-0000-0000000b0002', '00000000-0000-0000-0000-0000000b0003'));

DELETE FROM ticket_link
WHERE ticket_id IN (SELECT id FROM ticket WHERE organization_id IN ('00000000-0000-0000-0000-0000000b0001',
    '00000000-0000-0000-0000-0000000b0002', '00000000-0000-0000-0000-0000000b0003'));

DELETE FROM ticket_comment
WHERE ticket_id IN (SELECT id FROM ticket WHERE organization_id IN ('00000000-0000-0000-0000-0000000b0001',
    '00000000-0000-0000-0000-0000000b0002', '00000000-0000-0000-0000-0000000b0003'));

DELETE FROM ticket
WHERE organization_id IN ('00000000-0000-0000-0000-0000000b0001', '00000000-0000-0000-0000-0000000b0002',
    '00000000-0000-0000-0000-0000000b0003');

DELETE FROM app_user
WHERE id IN ('00000000-0000-0000-0000-00000000a003', '00000000-0000-0000-0000-00000000a004',
    '00000000-0000-0000-0000-00000000a005', '00000000-0000-0000-0000-00000000a006',
    '00000000-0000-0000-0000-00000000a007', '00000000-0000-0000-0000-00000000a008',
    '00000000-0000-0000-0000-00000000a009', '00000000-0000-0000-0000-00000000a010');

UPDATE app_user SET organization_id = NULL, team_id = NULL
WHERE id IN ('00000000-0000-0000-0000-00000000a001', '00000000-0000-0000-0000-00000000a002');

DELETE FROM team
WHERE id IN ('00000000-0000-0000-0000-0000000c0001', '00000000-0000-0000-0000-0000000c0002',
    '00000000-0000-0000-0000-0000000c0003');

DELETE FROM organization
WHERE id IN ('00000000-0000-0000-0000-0000000b0001', '00000000-0000-0000-0000-0000000b0002',
    '00000000-0000-0000-0000-0000000b0003');
